% ms-q2.tex
\msquestion{2}{7}

\begin{mspart}{(a)}
  \msstep{(i) \ T_n = 2 \times 3^{n-1}}{1A}
  \msstep{(ii) \ T_n = 8n - 20}{1A}
  \msstep{(iii) \ T_n = 125 \times \left(\dfrac{1}{5}\right)^{n-1} \text{ (or equivalent, e.g.\ } 5^{3-n}\text{)}}{1A}
  \msstep{(iv) \ T_n = \dfrac{n-3}{2n-1}}{1A}
\end{mspart}

\begin{mspart}{(b)}
